import './practice-lsit-photo.css';

/** Owner's original photo: the crop is CSS-only, with no retouching of the person. */
export default function PracticeLsitPhoto({lang}:{lang:string}) {
  return <figure className="practice-lsit">
    <span className="practice-lsit-layer practice-lsit-copper-layer" aria-hidden="true">
      <span className="practice-lsit-material practice-lsit-copper"/>
    </span>
    <span className="practice-lsit-layer practice-lsit-ink-layer" aria-hidden="true">
      <span className="practice-lsit-material practice-lsit-ink"/>
    </span>
    <div className="practice-lsit-crop">
      <img src="/media/practice-lsit-2026-11/praxe-original.jpg" width={960} height={1280}
        alt={lang==='en'?'Kryštof Švec holding an L-sit on a rock by the sea.':'Kryštof Švec drží L-sit na skále u moře.'}
        loading="eager" fetchPriority="high" decoding="async"/>
    </div>
  </figure>;
}

/* The same copper earth and black cotton as the two existing hero backgrounds. */
.practice-lsit {
  position:relative; isolation:isolate; width:100%; aspect-ratio:1.08;
  margin:0; background:none; border:0; box-shadow:none;
}
.practice-lsit-layer {
  position:absolute; pointer-events:none;
  filter:drop-shadow(0 2px 4px rgb(28 28 26 / 9%));
}
.practice-lsit-material {
  position:absolute; inset:0;
  -webkit-mask-size:100% 100%; mask-size:100% 100%;
  -webkit-mask-repeat:no-repeat; mask-repeat:no-repeat;
}
.practice-lsit-copper-layer {
  inset:0 6% 8% 2%; transform:rotate(-8deg);
}
.practice-lsit-copper {
  -webkit-mask-image:url('/media/practice-lsit-2026-11/copper-edge.svg');
  mask-image:url('/media/practice-lsit-2026-11/copper-edge.svg');
  background:#754437 url('/media/secondary-v9-10/burnt-earth-1254.webp') center/cover;
}
.practice-lsit-ink-layer {
  inset:9% 1% 0 6%; transform:rotate(8deg);
}
.practice-lsit-ink {
  -webkit-mask-image:url('/media/practice-lsit-2026-11/ink-edge.svg');
  mask-image:url('/media/practice-lsit-2026-11/ink-edge.svg');
  background:#1c1c1a var(--tex-cotton,url('/media/home-v9-1/ashes-1x.webp')) center/768px 768px;
}
.practice-lsit-crop {
  position:absolute; inset:8% 8% 8% 8%; overflow:hidden;
  border-radius:49% 51% 45% 55% / 47% 49% 51% 53%;
}
.practice-lsit .practice-lsit-crop img {
  /* A wider view uses more original pixels: pine canopy above, sea below right. */
  position:absolute; width:120%; max-width:none; height:auto;
  left:-12%; top:-40%; display:block; margin:0; border:0;
  transform:none; filter:none; opacity:1; object-fit:fill;
}
.tm-mobile[data-mobile-version] .m-hero.m-hero--practice[class] {
  display:block; height:auto; min-height:0;
}
.tm-mobile[data-mobile-version] .m-hero.m-hero--practice .m-hero-scene {
  flex:none;
  display:block; position:relative; width:100%; height:auto; min-height:0;
  max-height:none; aspect-ratio:auto; margin:12px 0 0; padding:10px 12px 22px;
  overflow:visible;
}
.tm-mobile[data-mobile-version] .m-hero.m-hero--practice .m-hero-scene>.m-material-edge {display:none;}
.tm-mobile[data-mobile-version] .m-hero.m-hero--practice .practice-lsit {max-width:660px;margin:0 auto;}
[data-secondary-v8] .practice-lsit-hero .practice-rock-layout:not(:has(>.practice-rock-photo)) {
  display:grid; grid-template-columns:minmax(0,1.15fr) minmax(0,1fr); align-items:center;
  gap:clamp(28px,5vw,80px); padding:64px var(--gutter) 72px; max-width:var(--maxw); min-height:0;
}
[data-secondary-v8] .practice-lsit-hero .practice-rock-layout:not(:has(>.practice-rock-photo)) .practice-rock-copy {
  grid-column:2; grid-row:1; width:100%; max-width:560px; margin:0; padding:0;
}
[data-secondary-v8] .practice-lsit-hero .practice-lsit {grid-column:1;grid-row:1;}
@media(max-width:1099px) {
  [data-secondary-v8] .practice-lsit-hero .practice-rock-layout:not(:has(>.practice-rock-photo)) {gap:28px;padding-top:40px;}
  [data-secondary-v8] .practice-lsit-hero .practice-rock-copy .h1 {font-size:clamp(2rem,4vw,3.25rem);}
}
